30	// A-16 (DEVDESK-143), the cross-cutting guard, started with the :jobs pilot
31	// (DEVDESK-142) and closed by its last story: no view is waiting any more.
32	//
33	// The guard answers one question for every view the router can build: is it on
34	// the activity column, or is it exempt for a stated reason? A view that is
35	// neither fails the test by name. For a migrated view it also checks the column,
36	// the help legend, the retired mechanisms in its declared sources (any tick
37	// included), and the footer of its selected row. There is no list of views
38	// waiting for their migration: exemptViews holds permanent, motivated exceptions.
39	
40	// activityView is what a migrated view exposes to the guard: read-only tables,
41	// keyed "<view>/<table>".
42	type activityView interface {
43		ActivityTables() map[string]datatable.ActivityTable
44	}
45	
46	// migratedTables are the tables already on the activity column, by view.
47	var migratedTables = map[command.ViewType][]string{
48		command.ViewJobs:         {"jobs/runs", "jobs/targets"},
49		command.ViewWorkspaces:   {"ws"},
50		command.ViewSecurity:     {"sec/inventory"},
51		command.ViewOCIResources: {"oci/images", "oci/networks", "oci/volumes", "oci/registries", "oci/registry-browser"},
52		command.ViewGitExplorer:  {"explorer/tree", "explorer/clone-list"},
53		command.ViewTemplates:    {"templates"},
54		command.ViewNetdiag:      {"netdiag/ports"},
55		command.ViewAgentUsage:   {"agent-usage/agents"},
56		command.ViewContainers:   {"containers"},
57	}
58	
59	// exemptViews have no long-running operation to show per row (inventory:
60	// "sans objet" or out of the batch), each with its reason.
61	var exemptViews = map[command.ViewType]string{
62		command.ViewDashboard:     "no table with row operations; the dashboard is a summary",
63		command.ViewStatus:        "monitors are polled as a whole, not per-row operations",
64		command.ViewGitAuth:       "a form, no table",
65		command.ViewConfiguration: "a form of settings, no table of operations",
66		command.ViewAbout:         "static facts, no table",
67		command.ViewFiles:         "out of the batch, candidate for a later S story (the delete goes through the registry, no story covers it)",
68		command.ViewViewer:        "a document pane, no table",
69	}
70	
71	// builtView returns the view the router builds for vt, laid out at 60x30.
72	func builtView(t *testing.T, vt command.ViewType) tea.Model {
73		t.Helper()
74		a := routerAt(t, &bareView{}, 60, 30) // isolateHome, session-only secrets
75		a.createView(vt)
76		var m tea.Model = a.views[vt] // Update returns a tea.Model, not a Screen
77		if m == nil {
78			t.Fatalf("view %q: the router did not build it", vt)
79		}
80		m, _ = m.Update(tea.WindowSizeMsg{Width: 60, Height: 30})
81		return m
82	}
83	
84	// classificationProblems says what is wrong with the classification of one
85	// view, empty when it is fine. A view is migrated (it has tables on the activity
86	// column) or exempt (with its reason), never both and never neither.
87	func classificationProblems(vt command.ViewType, migrated map[command.ViewType][]string, exempt map[command.ViewType]string) []string {
88		var problems []string
89		_, isExempt := exempt[vt]
90		isMigrated := len(migrated[vt]) > 0
91		switch {
92		case !isMigrated && !isExempt:
93			problems = append(problems, "neither migrated nor exempt (with its reason)")
94		case isMigrated && isExempt:
95			problems = append(problems, "both migrated and exempt")
96		}
97		return problems
98	}
99	
100	// Criterion 6: every view the router builds is migrated or exempt.
101	func TestActivityGuardEveryViewIsClassified(t *testing.T) {
102		for _, name := range command.AllViewNames() {
103			vt := command.ViewType(name)
104			t.Run(name, func(t *testing.T) {
105				for _, p := range classificationProblems(vt, migratedTables, exemptViews) {
106					t.Errorf("view %q is %s: classify it in activity_guard_test.go", vt, p)
107				}
108			})
109		}
110	}
111	
112	// The logic itself, on a fictitious view.
113	func TestActivityGuardClassificationLogic(t *testing.T) {
114		const v command.ViewType = "fiction"
115		tests := []struct {
116			name     string
117			migrated map[command.ViewType][]string
118			exempt   map[command.ViewType]string
119			problems int
120		}{
121			{"migrated is fine", map[command.ViewType][]string{v: {"fiction/a"}}, nil, 0},
122			{"exempt is fine", nil, map[command.ViewType]string{v: "why"}, 0},
123			{"unclassified fails", nil, nil, 1},
124			{"migrated and exempt fails", map[command.ViewType][]string{v: {"fiction/a"}}, map[command.ViewType]string{v: "why"}, 1},
125		}
126		for _, tt := range tests {
127			t.Run(tt.name, func(t *testing.T) {
128				if got := classificationProblems(v, tt.migrated, tt.exempt); len(got) != tt.problems {
129					t.Errorf("problems = %v, want %d", got, tt.problems)
130				}
131			})
132		}
133	}
134	
135	// Criteria 1, 4 and the help half of 5, at runtime, on the views the router builds.
136	func TestActivityGuardMigratedViews(t *testing.T) {
137		legendTitle := indicator.Legend().Title
138		for vt, want := range migratedTables {
139			t.Run(string(vt), func(t *testing.T) {
140				m := builtView(t, vt)
141				av, ok := m.(activityView)
142				if !ok {
143					t.Fatalf("view %q is migrated but does not expose ActivityTables()", vt)
144				}
145				tables := av.ActivityTables()
146				for _, name := range want {
147					tb, ok := tables[name]
148					if !ok {
149						t.Errorf("view %q: table %q is migrated but ActivityTables() does not report it (reported: %v)", vt, name, sortedKeys(tables))
150						continue
151					}
152					checkColumnZero(t, vt, name, tb.Shapes())
153					// Criterion 4, Rule 116: the rendered extent, never the sum of columns.
154					if got, want := tb.RenderedWidth(), 60-2; got != want {
155						t.Errorf("view %q table %q: RenderedWidth() = %d at 60 columns, want %d (Rule 116)", vt, name, got, want)
156					}
157				}
158				for name := range tables {
159					if !contains(want, name) {
160						t.Errorf("view %q reports table %q, which migratedTables does not list", vt, name)
161					}
162				}
163				// Criterion 5, help half: the legend.
164				hp, ok := m.(help.Provider)
165				if !ok {
166					t.Fatalf("view %q has no help", vt)
167				}
168				found := false
169				for _, s := range hp.GetHelpContent().Sections {
170					found = found || s.Title == legendTitle
171				}
172				if !found {
173					t.Errorf("view %q: help has no %q section (indicator.Legend)", vt, legendTitle)
174				}
175			})
176		}
177	}
178	
179	// Criterion 6, other direction: an exempt view must report no activity table.
180	func TestActivityGuardExemptViewsReportNoTable(t *testing.T) {
181		for vt := range exemptViews {
182			t.Run(string(vt), func(t *testing.T) {
183				if _, ok := builtView(t, vt).(activityView); ok {
184					t.Errorf("view %q exposes ActivityTables() but is exempt: move it out of exemptViews", vt)
185				}
186			})
187		}
188	}
189	
190	func checkColumnZero(t *testing.T, vt command.ViewType, table string, shapes []datatable.ColumnShape) {
191		t.Helper()
192		if len(shapes) == 0 {
193			t.Errorf("view %q table %q: no column reported", vt, table)
194			return
195		}
196		c := shapes[0]
197		var bad []string
198		if !c.Indicator {
199			bad = append(bad, "not an Indicator column")
200		}
201		if c.Title != "" {
202			bad = append(bad, fmt.Sprintf("title %q (want empty)", c.Title))
203		}
204		if c.Sizing != datatable.SizingFixed {
205			bad = append(bad, "not SizingFixed")
206		}
207		if c.MinWidth != datatable.IconColumnWidth {
208			bad = append(bad, fmt.Sprintf("MinWidth %d (want IconColumnWidth)", c.MinWidth))
209		}
210		if c.Less || c.Search {
211			bad = append(bad, "declares Less or Search")
212		}
213		if len(bad) > 0 {
214			t.Errorf("view %q table %q: column 0 is wrong: %s (A-16 criterion 1)", vt, table, strings.Join(bad, "; "))
215		}
216	}
217	
218	// migratedSources are the source prefixes (a directory ending in "/" or a file
219	// path, relative to internal/) of each migrated view. They are scanned for the
220	// retired mechanisms (criterion 2a/2b, and the hard-coded glyphs of 3). A prefix may be a file so a view
221	// that migrates in two steps (OCI A-09a/A-09a2/A-09b, explorer A-10a/b) can be scanned
222	// file by file.
223	var migratedSources = map[command.ViewType][]string{
224		command.ViewJobs:       {"ui/jobsview/"},
225		command.ViewWorkspaces: {"ui/workspaces/"},
226		command.ViewSecurity:   {"ui/security/"},
227		// OCI migrates in steps (A-09a images, A-09a2 registry browser, A-09b the rest):
228		// only the files that belong to the migrated tables are scanned. Excluded:
229		// commands.go (the refresh tea.Tick). The registry browser (A-09a2) is in.
230		command.ViewOCIResources: {
231			"ui/oci_resources/activity.go", "ui/oci_resources/table.go", "ui/oci_resources/jobs.go",
232			"ui/oci_resources/images.go", "ui/oci_resources/results.go", "ui/oci_resources/view.go",
233			"ui/oci_resources/model.go", "ui/oci_resources/busy.go", "ui/oci_resources/registries.go",
234			"ui/oci_resources/update.go", "ui/oci_resources/keys.go",
235			"ui/oci_resources/registry_browser.go", "ui/oci_resources/browser_keys.go",
236			"ui/oci_resources/browser_view.go", "ui/oci_resources/browser_state.go",
237			"ui/oci_resources/browser_bridge.go", "ui/oci_resources/browser_tags.go",
238		},
239		// The explorer is fully migrated (A-10a the tree, A-10b the clone list):
240		// the whole package is scanned.
241		command.ViewGitExplorer: {"ui/forge/explorer/"},
242		command.ViewTemplates:   {"ui/templates/"},
243		// Netdiag migrates only its Ports tab (A-12): the files that belong to it.
244		// Excluded: the diagnostics, interfaces and forward tabs, whose own spinners
245		// stay (the footers keep their own chains), and ports_commands.go (portsTickCmd
246		// is the data refresh tick, not a row animation).
247		command.ViewNetdiag: {"ui/netdiag/ports_model.go", "ui/netdiag/ports_activity.go"},
248		// The agent-usage view is fully migrated (A-13, DEVDESK-151): the whole package.
249		command.ViewAgentUsage: {"ui/agentusageview/"},
250		// Containers is fully migrated (A-14, DEVDESK-152) except commands.go, whose
251		// tea.Tick is the 2 s data refresh, and image_updates.go, ports.go and
252		// sources.go, which carry no row state.
253		command.ViewContainers: {"ui/containers/activity.go", "ui/containers/model.go", "ui/containers/update.go", "ui/containers/view.go"},
254	}
255	
256	// sourceDeclarationProblems says what is wrong with the link between migrated
257	// views and the sources scanned for them, empty when it is fine. files are the
258	// paths relative to internal/ of every non-test source file.
259	func sourceDeclarationProblems(migrated map[command.ViewType][]string, sources map[command.ViewType][]string, files []string) []string {
260		var problems []string
261		for vt := range migrated {
262			if len(sources[vt]) == 0 {
263				problems = append(problems, fmt.Sprintf("view %q is migrated but declares no source to scan in migratedSources", vt))
264			}
265		}
266		for vt, prefixes := range sources {
267			if len(migrated[vt]) == 0 {
268				problems = append(problems, fmt.Sprintf("view %q has sources in migratedSources but is not migrated (migratedTables)", vt))
269			}
270			for _, p := range prefixes {
271				if !anyHasPrefix(files, p) {
272					problems = append(problems, fmt.Sprintf("view %q: source prefix %q matches no file", vt, p))
273				}
274			}
275		}
276		sort.Strings(problems)
277		return problems
278	}
279	
280	func anyHasPrefix(files []string, prefix string) bool {
281		for _, f := range files {
282			if prefix != "" && strings.HasPrefix(f, prefix) {
283				return true
284			}
285		}
286		return false
287	}
288	
289	// Criteria 2b and 6: the sources scanned are exactly those of the migrated views.
290	func TestActivityGuardMigratedSourcesAreDeclared(t *testing.T) {
291		var files []string
292		sourceFiles(t, func(rel string, _ *token.FileSet, _ *ast.File) { files = append(files, rel) })
293		for _, p := range sourceDeclarationProblems(migratedTables, migratedSources, files) {
294			t.Error(p)
295		}
296	}
