143					t.Fatalf("view %q is migrated but does not expose ActivityTables()", vt)
144				}
145				tables := av.ActivityTables()
146				for _, name := range want {
147					tb, ok := tables[name]
148					if !ok {
149						t.Errorf("view %q: table %q is migrated but ActivityTables() does not report it (reported: %v)", vt, name, sortedKeys(tables))
150						continue
151					}
152					checkColumnZero(t, vt, name, tb.Shapes())
153					// Criterion 4, Rule 116: the rendered extent, never the sum of columns.
154					if got, want := tb.RenderedWidth(), 60-2; got != want {
155						t.Errorf("view %q table %q: RenderedWidth() = %d at 60 columns, want %d (Rule 116)", vt, name, got, want)
156					}
157				}
158				for name := range tables {
159					if !contains(want, name) {
160						t.Errorf("view %q reports table %q, which migratedTables does not list", vt, name)
161					}
162				}
163				// Criterion 5, help half: the legend.
164				hp, ok := m.(help.Provider)
165				if !ok {
166					t.Fatalf("view %q has no help", vt)
167				}
168				found := false
169				for _, s := range hp.GetHelpContent().Sections {
170					found = found || s.Title == legendTitle
171				}
172				if !found {
173					t.Errorf("view %q: help has no %q section (indicator.Legend)", vt, legendTitle)
174				}
175			})
176		}
177	}
