190	func checkColumnZero(t *testing.T, vt command.ViewType, table string, shapes []datatable.ColumnShape) {
191		t.Helper()
192		if len(shapes) == 0 {
193			t.Errorf("view %q table %q: no column reported", vt, table)
194			return
195		}
196		c := shapes[0]
197		var bad []string
198		if !c.Indicator {
199			bad = append(bad, "not an Indicator column")
200		}
201		if c.Title != "" {
202			bad = append(bad, fmt.Sprintf("title %q (want empty)", c.Title))
203		}
204		if c.Sizing != datatable.SizingFixed {
205			bad = append(bad, "not SizingFixed")
206		}
207		if c.MinWidth != datatable.IconColumnWidth {
208			bad = append(bad, fmt.Sprintf("MinWidth %d (want IconColumnWidth)", c.MinWidth))
209		}
210		if c.Less || c.Search {
211			bad = append(bad, "declares Less or Search")
212		}
213		if len(bad) > 0 {
214			t.Errorf("view %q table %q: column 0 is wrong: %s (A-16 criterion 1)", vt, table, strings.Join(bad, "; "))
215		}
216	}
