256	// sourceDeclarationProblems says what is wrong with the link between migrated
257	// views and the sources scanned for them, empty when it is fine. files are the
258	// paths relative to internal/ of every non-test source file.
259	func sourceDeclarationProblems(migrated map[command.ViewType][]string, sources map[command.ViewType][]string, files []string) []string {
260		var problems []string
261		for vt := range migrated {
262			if len(sources[vt]) == 0 {
263				problems = append(problems, fmt.Sprintf("view %q is migrated but declares no source to scan in migratedSources", vt))
264			}
265		}
266		for vt, prefixes := range sources {
267			if len(migrated[vt]) == 0 {
268				problems = append(problems, fmt.Sprintf("view %q has sources in migratedSources but is not migrated (migratedTables)", vt))
269			}
270			for _, p := range prefixes {
271				if !anyHasPrefix(files, p) {
272					problems = append(problems, fmt.Sprintf("view %q: source prefix %q matches no file", vt, p))
273				}
274			}
275		}
276		sort.Strings(problems)
277		return problems
278	}
279	
280	func anyHasPrefix(files []string, prefix string) bool {
281		for _, f := range files {
282			if prefix != "" && strings.HasPrefix(f, prefix) {
283				return true
284			}
285		}
286		return false
287	}
