1	package ociresources
2	
3	import (
4		"strings"
5	
6		"charm.land/bubbles/v2/spinner"
7		tea "charm.land/bubbletea/v2"
8	
9		"github.com/anthnel/devdesk/internal/config"
10		"github.com/anthnel/devdesk/internal/docker"
11		"github.com/anthnel/devdesk/internal/ui/keymap"
12	)
13	
14	// InEditMode returns true when a text input is active (blocks command mode).
15	func (b *RegistryBrowser) InEditMode() bool {
16		if b.state == browserStateInput && b.focusedField == brFieldRepo {
17			return true
18		}
19		return b.state == browserStateTags && b.filterActive
20	}
21	
22	// IsSearching returns true while registry tag queries are still in flight.
23	func (b *RegistryBrowser) IsSearching() bool {
24		return b.pendingSearches > 0
25	}
26	
27	// Update handles all messages for the browser.
28	func (b *RegistryBrowser) Update(msg tea.Msg) (*RegistryBrowser, tea.Cmd) {
29		switch msg := msg.(type) {
30		case tea.KeyPressMsg:
31			return b.handleKeyMsg(msg)
32		case spinner.TickMsg:
33			// Only a search turns this spinner, and it shows in the footer: a tag's
34			// state is drawn by the activity column, which jobs.FrameMsg animates.
35			if b.pendingSearches > 0 {
36				var cmd tea.Cmd
37				b.spinner, cmd = b.spinner.Update(msg)
38				return b, cmd
39			}
40			return b, nil
41		}
42		return b.delegateUpdate(msg)
43	}
44	
45	func (b *RegistryBrowser) delegateUpdate(msg tea.Msg) (*RegistryBrowser, tea.Cmd) {
46		if b.state == browserStateInput && b.focusedField == brFieldRepo {
47			var cmd tea.Cmd
48			b.repoInput, cmd = b.repoInput.Update(msg)
49			return b, cmd
50		}
51		if b.state == browserStateTags {
52			if b.filterActive {
53				var cmd tea.Cmd
54				b.filterInput, cmd = b.filterInput.Update(msg)
55				b.rebuildTagTable()
56				return b, cmd
57			}
58			return b, b.tagTable.Update(msg)
59		}
60		return b, nil
61	}
62	
63	func (b *RegistryBrowser) handleKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
64		switch b.state {
65		case browserStateInput:
66			return b.handleInputKeyMsg(msg)
67		case browserStateTags:
68			return b.handleTagsKeyMsg(msg)
69		}
70		return b, nil
71	}
72	
73	func (b *RegistryBrowser) handleInputKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
74		switch msg.String() {
75		case "esc":
76			return b, func() tea.Msg { return RegistryBrowserCloseMsg{} }
77		case "down":
78			b.focusedField = min(b.focusedField+1, b.brFieldSubmit())
79			b.updateFocus()
80			return b, nil
81		case "up":
82			b.focusedField = max(b.focusedField-1, brFieldRepo)
83			b.updateFocus()
84			return b, nil
85		case keymap.Space:
86			if b.focusedField >= 1 && b.focusedField <= len(b.rows) {
87				row := b.rows[b.focusedField-1]
88				if row.groupSlug != "" {
89					b.toggleGroup(row.groupSlug)
90					return b, nil
91				}
92				key := b.entries[row.entry].key
93				b.selectedRegs[key] = !b.selectedRegs[key]
94				return b, nil
95			}
96		case "enter":
97			if b.focusedField == brFieldRepo || b.focusedField == b.brFieldSubmit() {
98				return b.submitSearch()
99			}
100			b.focusedField = min(b.focusedField+1, b.brFieldSubmit())
101			b.updateFocus()
102			return b, nil
103		}
104		return b.delegateUpdate(msg)
105	}
106	
107	// credsFor returns the credentials to search entry with, and nothing at all
108	// when the registry — or the group it belongs to — is marked anonymous (D12).
109	// Docker keys credentials by host, so a Nexus instance with one repository
110	// logged into would otherwise send that login to every repository it serves.
111	func (b *RegistryBrowser) credsFor(entry browserRegistryEntry) (string, string) {
112		if !config.UsesCredentials(entry.authMode) {
113			return "", ""
114		}
115		// Credentials come from the parent registry, or the entry itself for a
116		// registry that is not a group member.
117		credURL := entry.URL
118		if entry.parentURL != "" {
119			credURL = entry.parentURL
120		}
121		var username string
122		for _, reg := range b.registries {
123			if reg.URL == credURL {
124				username = reg.Username
125				break
126			}
127		}
128		storedUser, storedPass, _ := docker.GetStoredCreds(credURL)
129		if username == "" {
130			username = storedUser
131		}
132		return username, storedPass
133	}
134	
135	func (b *RegistryBrowser) submitSearch() (*RegistryBrowser, tea.Cmd) {
136		repo := strings.TrimSpace(b.repoInput.Value())
137		if repo == "" {
138			return b, nil
139		}
140	
141		b.tags = nil
142		b.registryFilter = resultFilter{}
143		b.pendingSearches = 0
144		b.filterInput.SetValue("")
145		b.filterActive = false
146		// A new search starts from the default order, not wherever the last one's
147		// `.` presses left the table.
148		b.tagTable.SetSort(tagColumnTag, false)
149	
150		var cmds []tea.Cmd
151		for _, entry := range b.entries {
152			if !b.selected(entry) {
153				continue
154			}
155			username, storedPass := b.credsFor(entry)
156			alias := entry.Alias
157			if entry.ParentAlias != "" {
158				alias = entry.ParentAlias + "/" + entry.Alias
159			}
160			// The prefix is applied here and nowhere else: it is then already part
161			// of MultiRegistryTag.Repo, so multiImageName and registryAPIURL need to
162			// know nothing about it. Teaching both would be two places free to
163			// drift, which is the disagreement D39 already is (§3.18).
164			normalizedRepo := joinRepoPrefix(entry.repoPrefix, normalizeRepoForRegistry(entry.URL, repo))
165			apiURL := registryAPIURL(entry.URL)
166			b.pendingSearches++
167			cmds = append(cmds, searchRegistryTagsCmd(entry.key, entry.URL, alias, apiURL, normalizedRepo, username, storedPass))
168		}
169	
170		if len(cmds) == 0 {
171			return b, nil
172		}
173	
174		b.state = browserStateTags
175		b.tagTable.Focus()
176		b.rebuildTagTable()
177		cmds = append(cmds, b.spinner.Tick)
178		return b, tea.Batch(cmds...)
179	}
180	
181	func (b *RegistryBrowser) handleTagsKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
182		if b.filterActive {
183			switch msg.String() {
184			case "esc", "enter":
185				b.filterActive = false
186				b.filterInput.Blur()
187				b.rebuildTagTable()
188				b.resizeTagTable()
189				return b, nil
190			}
191			return b.delegateUpdate(msg)
192		}
193	
194		switch msg.String() {
195		case "esc":
196			b.state = browserStateInput
197			b.tagTable.Blur()
198			b.updateFocus()
199			return b, nil
200		case "/":
201			b.filterActive = true
202			b.filterInput.Focus()
203			b.resizeTagTable()
204			return b, nil
205		case "r":
206			b.cycleRegistryFilter()
207			return b, nil
208		case "enter":
209			return b.openTagScanDetails()
210		case keymap.Get:
211			return b.pullSelectedTag()
212		case keymap.Scan:
213			return b.requestDirectScan()
214		}
215		// Navigation and `.` are the table's. `/` never reaches it: the browser's
216		// own filter took the key two cases above, and the table declares no
217		// searchable column, so it would decline it anyway.
218		return b, b.tagTable.Update(msg)
219	}
220

120	//
121	// It holds no state of its own for it any more (§3.60). The browser used to
122	// take over the screen with a spinner of its own until the pull answered,
123	// which said less than the Images tab now does — the row is there, spinning,
124	// next to every other image — and said it on the one screen from which the
125	// result could not be seen.
126	func (b *RegistryBrowser) pullSelectedTag() (*RegistryBrowser, tea.Cmd) {
127		name := b.selectedImageName()
128		if name == "" {
129			return b, nil
130		}
131		return b, func() tea.Msg { return RegistryPullRequestedMsg{ImageName: name} }
132	}
133	
134	// requestDirectScan emits RegistryTagDirectScanMsg for a remote Trivy scan (no pull).
135	func (b *RegistryBrowser) requestDirectScan() (*RegistryBrowser, tea.Cmd) {
136		name := b.selectedImageName()
137		if name == "" {
138			return b, nil
139		}
140		return b, func() tea.Msg { return RegistryTagDirectScanMsg{ImageName: name} }
141	}
142	
143	// openTagScanDetails emits ScanDetailsRequestMsg when the selected tag has cached results.
144	func (b *RegistryBrowser) openTagScanDetails() (*RegistryBrowser, tea.Cmd) {
145		name := b.selectedImageName()
146		if name == "" {
147			return b, nil
148		}
149		if _, ok := b.scanCache[name]; !ok {
150			return b, nil
151		}
152		return b, func() tea.Msg { return ScanDetailsRequestMsg{ImageName: name} }
153	}
154	
155	// joinRepoPrefix puts an entry's prefix in front of the repository name.
156	//
157	// One slash, always: the prefix is a path segment and normalization has already
158	// refused one carrying a slash at either end, so there is nothing here to guess
159	// about (§3.18).
160	func joinRepoPrefix(prefix, repo string) string {
161		if prefix == "" {
162			return repo
163		}
164		return prefix + "/" + repo
165	}
166	
167	// normalizeRepoForRegistry prepends "library/" for bare names on Docker Hub.
168	func normalizeRepoForRegistry(registryURL, repo string) string {
169		if strings.Contains(repo, "/") {
170			return repo
171		}
172		if isDockerHub(registryURL) {
173			return "library/" + repo
174		}
175		return repo
176	}
177	
178	// registryHost strips the scheme from a configured registry URL, leaving what
179	// Docker itself is keyed on: `host[:port]`, plus whatever path a repository
180	// manager serves the registry under.
181	//
182	// A registry URL is written either way in practice — the form does not
183	// normalize it, `registryAPIURL` explicitly accepts both, and this package's own
184	// examples write `https://nexus.example.com/repository/docker-group`. Every
185	// Docker-facing use has to strip it, and none of the three that needed to did
186	// (D39): a `docker pull` reference carrying `https://` is not a reference at
187	// all, and a hub alias compared against a scheme-bearing string never matched,
188	// so images from a Hub configured as `https://docker.io` lost their `library/`
189	// prefix.
190	func registryHost(registryURL string) string {
191		base := strings.TrimSuffix(strings.TrimSpace(registryURL), "/")
192		for _, scheme := range []string{"https://", "http://"} {
193			if len(base) >= len(scheme) && strings.EqualFold(base[:len(scheme)], scheme) {
194				return base[len(scheme):]
195			}
196		}
197		return base
198	}
199	
200	// isDockerHub reports whether a registry URL names Docker Hub, under either of
201	// the two spellings and with or without a scheme. Hub is the one registry whose
202	// references carry no host, so every caller has to recognise it.
203	func isDockerHub(registryURL string) bool {
204		host := registryHost(registryURL)
205		return strings.EqualFold(host, "docker.io") || strings.EqualFold(host, "registry-1.docker.io")
206	}
207	
208	// multiImageName constructs the full image reference for pull/scan.
209	//
210	// A Hub reference carries no host under docker: `docker pull nginx` leaves
211	// `nginx` as the local repository name, and qualifying it would only make the
212	// Images tab show `docker.io/library/nginx` next to a `nginx` pulled by hand.
213	// Podman disagrees, and not cosmetically — measured against a real podman
214	// with no `unqualified-search-registries` configured (§3.67), which is the
215	// package default on Debian/Ubuntu and Fedora alike: `podman pull
216	// library/nginx:tag` refuses outright ("short-name ... did not resolve to an
217	// alias and no unqualified-search registries are defined"), where docker
218	// would have silently assumed Hub. So the bare form is kept for docker, where
219	// it has always worked, and only podman gets the explicit host — which is
220	// also the form its own `images` list already uses (§3.67), so nothing about
221	// this makes a podman-pulled image look different from one already there.
222	func multiImageName(registryURL, repo, tag string) string {
223		if isDockerHub(registryURL) {
224			if engine.Current().Name == engine.Podman {
225				return "docker.io/" + repo + ":" + tag
226			}
227			return repo + ":" + tag
228		}
229		return registryHost(registryURL) + "/" + repo + ":" + tag
230	}
231	
232	func (b *RegistryBrowser) updateFocus() {
233		b.repoInput.Blur()
234		if b.focusedField == brFieldRepo {
235			b.repoInput.Focus()
236		}
237	}
238	
239	// filteredMultiTags returns the tags the registry filter and the text filter let
240	// through. The order is the table's — it is what holds the cursor and the
241	// header arrow together.
242	func (b *RegistryBrowser) filteredMultiTags() []MultiRegistryTag {
243		query := strings.ToLower(b.filterInput.Value())
244		var result []MultiRegistryTag
245		for _, t := range b.tags {
246			if !b.registryFilter.matches(t.EntryKey, b.entryFor(t.EntryKey)) {
247				continue
248			}
249			if query != "" && !strings.Contains(strings.ToLower(t.Tag), query) &&
250				!strings.Contains(strings.ToLower(t.Repo), query) {
251				continue
252			}
253			result = append(result, t)
254		}
255		return result
256	}
