13	// rebuildTagTable re-decorates the rows and hands them to the table.
14	//
15	// The decoration — the scan counts, whether a scan is running, the registry's
16	// label — is not on the tag, and the columns are built once so they cannot
17	// reach the browser for it. So it is recomputed wholesale on every change,
18	// exactly as the images tab does with imageRow.
19	//
20	// The filters are applied here because they narrow the tags before the table
21	// sees them; the sort and the header arrows are the table's.
22	func (b *RegistryBrowser) rebuildTagTable() {
23		tags := b.filteredMultiTags()
24	
25		rows := make([]tagRow, len(tags))
26		for i, t := range tags {
27			imageName := multiImageName(t.RegistryURL, t.Repo, t.Tag)
28			label := t.Alias
29			if label == "" {
30				label = t.RegistryURL
31			}
32			entry, scanned := b.scanCache[imageName]
33			rows[i] = tagRow{
34				tag:         t,
35				label:       label,
36				entry:       entry,
37				scanned:     scanned,
38				Activity:    b.tagActivity(imageName),
39				ScanRunning: b.scanRunning(imageName),
40			}
41		}
42	
43		b.tagTable.SetItems(rows)
44		b.resizeTagTable()
45	}
46	
47	// tagActivity resolves what one tag row says about its activity: a scan or a
48	// pull, whoever started it, or a remembered failure of either. Both are read
49	// against the context the snapshot carries, with the raw reference as identity.
50	func (b *RegistryBrowser) tagActivity(imageName string) components.RowActivity {
51		return components.DescribeRow(components.RowQuery{
52			Runs: b.jobs, Failures: b.failures, Context: b.contextName,
53			Target: jobs.TargetKey(imageName), Kinds: ociKinds,
54		})
55	}
56	
57	// scanRunning reports whether a scan of the tag runs now. A queued scan does
58	// not: it keeps its counts.
59	func (b *RegistryBrowser) scanRunning(imageName string) bool {
60		for _, a := range jobs.ActiveOn(b.jobs, b.contextName, imageName, jobs.KindScan) {
61			if a.Item.State == jobs.ItemRunning {
62				return true
63			}
64		}
65		return false
66	}
