78	func (b *RegistryBrowser) viewInput() string {
79		var sb strings.Builder
80	
81		sb.WriteString(theme.EmptyLineBg(b.width) + "\n")
82		sb.WriteString(b.renderInputField("Repository", b.repoInput.View(), brFieldRepo))
83		sb.WriteString("\n\n")
84	
85		if len(b.rows) > 0 {
86			sb.WriteString(theme.Bg("  ") + theme.DimStyle.Render("Registries:") + "\n")
87			for i, row := range b.rows {
88				focused := b.focusedField == b.brFieldReg(i)
89				if row.groupSlug != "" {
90					// One checkbox for the whole group, with a third state for a
91					// partial selection — eight proxies are not eight keystrokes.
92					sb.WriteString(theme.RenderCheckboxTri(b.groupState(row.groupSlug), row.label, focused))
93				} else {
94					sb.WriteString(theme.RenderCheckbox(b.selected(b.entries[row.entry]), row.label, focused))
95				}
96				if i < len(b.rows)-1 {
97					sb.WriteString("\n")
98				}
99			}
100			sb.WriteString("\n\n")
101		}
102	
103		sb.WriteString("  ")
104		sb.WriteString(theme.RenderButton("Browse Tags", b.focusedField == b.brFieldSubmit(), "primary"))
105	
106		return sb.String()
107	}
