109	func (b *RegistryBrowser) renderInputField(label, value string, fieldIdx int) string {
110		var labelStr string
111		if b.focusedField == fieldIdx {
112			labelStr = theme.KeyStyle.Render(theme.IconCircleSmall + " " + label + " " + theme.IconChevronRight)
113		} else {
114			labelStr = theme.Bg("  " + label + " " + theme.IconChevronRight)
115		}
116		return labelStr + "\n  " + value
117	}
