126	// LoadingLabel names what the browser is fetching, for the OCI view's footer.
127	// The second result is false when nothing is in flight.
128	func (b *RegistryBrowser) LoadingLabel() (string, bool) {
129		if b.state == browserStateTags && b.pendingSearches > 0 {
130			return "Searching registries...", true
131		}
