74	// WantsBlink reports whether a visible tag row has a running operation.
75	func (b *RegistryBrowser) WantsBlink() bool {
76		if b.state != browserStateTags {
77			return false
78		}
79		for _, r := range b.tagTable.Items() {
80			if r.Activity.State == indicator.Running {
81				return true
82			}
83		}
84		return false
85	}
