105	// SetOperationError, SetOperationSuccess and OperationImageName went with the
106	// status screen (§3.60): the browser is closed by the time a pull answers, and
107	// the answer goes to the footer and the Images list.
108	
109	// selectedImageName returns the full image reference for the focused table row.
110	func (b *RegistryBrowser) selectedImageName() string {
111		t := b.getSelectedMultiTag()
112		if t == nil {
113			return ""
114		}
115		return multiImageName(t.RegistryURL, t.Repo, t.Tag)
116	}
