382	func searchRegistryTagsCmd(entryKey, registryURL, alias, apiURL, repo, username, password string) tea.Cmd {
383		return func() tea.Msg {
384			tags, err := oci.ListRegistryTags(apiURL, repo, username, password)
385			return MultiRegistryTagsLoadedMsg{
386				EntryKey: entryKey, RegistryURL: registryURL, Alias: alias, Repo: repo, Tags: tags, Err: err,
387			}
