340	func copyToClipboardCmd(text string) tea.Cmd {
341		return func() tea.Msg {
342			err := clipboard.WriteAll(text)
343			return ClipboardCopyMsg{Err: err}
344		}
345	}
346	
347	// verifyEntrypointCmd checks if an entrypoint binary exists inside an image.
348	// Uses a 600ms debounce delay so rapid keystrokes don't flood docker.
349	// The seq parameter guards against stale results: results are discarded if seq
350	// no longer matches the form's current verifySeq when the message is received.
351	func verifyEntrypointCmd(seq int, image, entrypoint string) tea.Cmd {
352		return func() tea.Msg {
353			time.Sleep(600 * time.Millisecond)
354			ok, _ := docker.VerifyEntrypoint(image, entrypoint)
355			return EntrypointVerifyFinishedMsg{Seq: seq, OK: ok}
356		}
357	}
358	
359	// ---- Registry browser commands ----
360	
361	var ociHTTPClient = &http.Client{Timeout: 15 * time.Second}
362	
363	// registryAPIURL converts a user-specified registry URL into a v2 API base URL.
364	//
365	// This is the one place that *keeps* a scheme rather than stripping it: an
366	// explicit `http://` is how a registry on a plain-HTTP port is reached, and
367	// upgrading it would break that registry rather than fix anything. Everything
368	// Docker-facing goes through registryHost instead (D39).
369	func registryAPIURL(registryURL string) string {
370		base := strings.TrimSuffix(strings.TrimSpace(registryURL), "/")
371		if isDockerHub(base) {
372			return "https://registry-1.docker.io"
373		}
374		lower := strings.ToLower(base)
375		if !strings.HasPrefix(lower, "http://") && !strings.HasPrefix(lower, "https://") {
376			return "https://" + base
377		}
378		return base
379	}
380	
381	// searchRegistryTagsCmd fetches tags from one registry and returns a MultiRegistryTagsLoadedMsg.
382	func searchRegistryTagsCmd(entryKey, registryURL, alias, apiURL, repo, username, password string) tea.Cmd {
383		return func() tea.Msg {
384			tags, err := oci.ListRegistryTags(apiURL, repo, username, password)
385			return MultiRegistryTagsLoadedMsg{
386				EntryKey: entryKey, RegistryURL: registryURL, Alias: alias, Repo: repo, Tags: tags, Err: err,
387			}
388		}
389	}
390	
391	// fetchDockerHubTagsMeta fetches last_updated times from the Docker Hub public API.
392	// Works for public repos (no auth needed). Returns partial results on error.
393	func fetchDockerHubTagsMeta(namespace, repo string) (map[string]time.Time, error) {
394		endpoint := fmt.Sprintf("https://hub.docker.com/v2/repositories/%s/%s/tags?page_size=100&ordering=last_updated", namespace, repo)
395		req, err := http.NewRequest("GET", endpoint, nil)
396		if err != nil {
397			return nil, err
398		}
399		req.Header.Set("Accept", "application/json")
400		resp, err := ociHTTPClient.Do(req)
401		if err != nil {
402			return nil, err
403		}
404		defer func() { _ = resp.Body.Close() }()
405		if resp.StatusCode != http.StatusOK {
406			return nil, fmt.Errorf("hub API returned %d", resp.StatusCode)
407		}
408		body, err := io.ReadAll(resp.Body)
409		if err != nil {
410			return nil, err
411		}
412		var result struct {
413			Results []struct {
414				Name        string `json:"name"`
415				LastUpdated string `json:"last_updated"`
416			} `json:"results"`
417		}
418		if err := json.Unmarshal(body, &result); err != nil {
419			return nil, err
420		}
421		meta := make(map[string]time.Time, len(result.Results))
422		for _, r := range result.Results {
423			if t, err := time.Parse(time.RFC3339Nano, r.LastUpdated); err == nil {
424				meta[r.Name] = t
425			}
426		}
427		return meta, nil
428	}
429	
430	// loadMultiRegistryTagsMetaCmd fetches tag metadata for one registry in the background.
431	// For Docker Hub it uses the Hub API; other registries return empty (no error).
432	func loadMultiRegistryTagsMetaCmd(entryKey, registryURL, repo string) tea.Cmd {
433		return func() tea.Msg {
434			empty := MultiRegistryTagsMetaMsg{EntryKey: entryKey, RegistryURL: registryURL, Repo: repo}
435			base := strings.ToLower(strings.TrimSuffix(registryURL, "/"))
436			isDockerhub := base == "docker.io" || base == "registry-1.docker.io"
437			if !isDockerhub {
438				return empty
439			}
440			parts := strings.SplitN(repo, "/", 2)
441			if len(parts) != 2 {
442				return empty
443			}
444			meta, err := fetchDockerHubTagsMeta(parts[0], parts[1])
445			return MultiRegistryTagsMetaMsg{
446				EntryKey: entryKey, RegistryURL: registryURL, Repo: repo, Meta: meta, Err: err,
447			}
448		}
449	}
450	
451	// pullOneImageCmd pulls a Docker image to the local store, emitting
452	// RegistryPullStartingMsg before and RegistryPullCompleteMsg after — the pair
453	// jobs.Start needs to track the run (mirrors scanOneImageCmd).
454	//
455	// The pull is verified first (§3.82): deps says how, and a pull its signature
456	// check blocks comes back as an imagepull.BlockedError.
457	func pullOneImageCmd(imageName string, deps imagepull.Deps) tea.Cmd {
458		// The context the pull runs under, so `K` can stop it (D7). It travels on
459		// the starting message, which is the same Update that marks the item
460		// running — two steps would leave a window where the row is running and
461		// cannot be stopped.
462		ctx, cancel := context.WithCancel(context.Background())
463	
464		return tea.Sequence(
465			func() tea.Msg { return RegistryPullStartingMsg{ImageName: imageName, Cancel: cancel} },
466			func() tea.Msg {
467				// Releases the context whether the pull was cancelled or ran to the
468				// end; the registry drops its copy when the item settles.
469				defer cancel()
470	
471				check, err := imagepull.Pull(ctx, imageName, deps)
472				return RegistryPullCompleteMsg{ImageName: imageName, Err: err, Check: check}
473			},
474		)

1	package oci
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"io"
7		"net/http"
8		"net/url"
9		"strings"
10		"time"
11	)
12	
13	// registryHTTPClient is swapped by tests that must reach a stand-in for a
14	// registry by another address.
15	var registryHTTPClient = &http.Client{Timeout: 15 * time.Second}
16	
17	const (
18		// maxTagPages bounds how many pages of a tag list are followed. A registry
19		// that pages (`?n=`, `Link: rel="next"`) answers a page at a time, and one
20		// that keeps answering "next" must not hold a caller forever.
21		maxTagPages = 100
22		// maxTagResponse bounds one page. Docker Hub answers a whole list in one
23		// response when no page size is given — measured at 9 125 tags for
24		// library/node (§3.2) — so the bound is generous, but it is a bound.
25		maxTagResponse = 32 << 20
26	)
27	
28	// ListRegistryTags lists the tags of a repository through the registry's v2 API.
29	//
30	// apiURL is the API base (see the browser's registryAPIURL). Credentials, when
31	// given, go as Basic auth and, on a 401 that names a Bearer realm, to that
32	// realm's token endpoint — the flow Docker Hub and most hosted registries use.
33	// The token is kept for the following pages.
34	//
35	// The list is followed across pages: whatever a registry caps a response at,
36	// and Docker Hub does not, a repository with more tags than one page holds is
37	// returned whole. This is the one tag lister that speaks the Bearer flow; the
38	// template client's ListTags (Client.ListTags) reads a registry the user
39	// configured for templates and only ever sends Basic auth.
40	func ListRegistryTags(apiURL, repo, username, password string) ([]string, error) {
41		next := fmt.Sprintf("%s/v2/%s/tags/list", strings.TrimSuffix(apiURL, "/"), repo)
42		var (
43			tags  []string
44			token string
45		)
46		for page := 0; next != ""; page++ {
47			if page == maxTagPages {
48				return nil, fmt.Errorf("tag list of %s is longer than %d pages", repo, maxTagPages)
49			}
50			body, link, usedToken, err := registryGET(next, username, password, token)
51			if err != nil {
52				return nil, err
53			}
54			token = usedToken
55			var result struct {
56				Tags []string `json:"tags"`
57			}
58			if err := json.Unmarshal(body, &result); err != nil {
59				return nil, fmt.Errorf("decode tags response: %w", err)
60			}
61			tags = append(tags, result.Tags...)
62			next = resolveNext(next, link)
63		}
64		return tags, nil
65	}
66	
67	// registryGET performs a GET, answering a Bearer challenge once. It returns the
68	// body, the Link header, and the token to send on the following requests.
69	func registryGET(rawURL, username, password, token string) (body []byte, link, usedToken string, err error) {
70		resp, token, err := registryDo(http.MethodGet, rawURL, "", username, password, token)
71		if err != nil {
72			return nil, "", token, err
73		}
74		defer func() { _ = resp.Body.Close() }()
75		if resp.StatusCode != http.StatusOK {
76			return nil, "", token, fmt.Errorf("registry returned %d", resp.StatusCode)
77		}
78		body, err = io.ReadAll(io.LimitReader(resp.Body, maxTagResponse))
79		return body, resp.Header.Get("Link"), token, err
80	}
81	
82	// registryDo sends one request, answering a Bearer challenge once. The caller
83	// closes the response body and reads the status.
84	func registryDo(method, rawURL, accept, username, password, token string) (*http.Response, string, error) {
85		resp, err := doRequest(method, rawURL, accept, username, password, token)
86		if err != nil {
87			return nil, token, err
88		}
89		if resp.StatusCode != http.StatusUnauthorized {
90			return resp, token, nil
91		}
92		challenge := resp.Header.Get("Www-Authenticate")
93		_ = resp.Body.Close()
94		if !strings.HasPrefix(challenge, "Bearer ") {
95			return nil, token, fmt.Errorf("unexpected auth challenge: %s", challenge)
96		}
97		token, err = exchangeBearerToken(challenge[7:], username, password)
98		if err != nil {
99			return nil, "", err
100		}
101		if resp, err = doRequest(method, rawURL, accept, "", "", token); err != nil {
102			return nil, token, fmt.Errorf("%s (retry) %s: %w", method, rawURL, err)
103		}
104		return resp, token, nil
105	}
106	
107	// doRequest sends one request: a bearer token when there is one, Basic auth
108	// when there are credentials and no token.
109	func doRequest(method, rawURL, accept, username, password, token string) (*http.Response, error) {
110		req, err := http.NewRequest(method, rawURL, nil)
111		if err != nil {
112			return nil, fmt.Errorf("build request: %w", err)
113		}
114		if accept != "" {
115			req.Header.Set("Accept", accept)
116		}
117		switch {
118		case token != "":
119			req.Header.Set("Authorization", "Bearer "+token)
120		case username != "" && password != "":
121			req.SetBasicAuth(username, password)
122		}
123		resp, err := registryHTTPClient.Do(req)
124		if err != nil {
125			return nil, fmt.Errorf("%s %s: %w", method, rawURL, err)
126		}
127		return resp, nil
128	}
129	
130	// manifestAccept lists every manifest kind a tag can point to. A multi-platform
131	// tag is an index (or a Docker manifest list), and its digest is the one `docker
132	// pull` records in RepoDigests; asking for a single-platform manifest only
133	// would make the registry convert or refuse, and the digests would not match.
134	var manifestAccept = strings.Join([]string{
135		"application/vnd.oci.image.index.v1+json",
136		"application/vnd.docker.distribution.manifest.list.v2+json",
137		"application/vnd.oci.image.manifest.v1+json",
138		"application/vnd.docker.distribution.manifest.v2+json",
139	}, ", ")
140	
141	// ManifestDigest returns the digest a tag currently points to, from the
142	// registry's Docker-Content-Digest header.
143	//
144	// It is a HEAD request: Docker Hub does not count a HEAD against the pull rate
145	// limit, and nothing but the header is needed.
146	func ManifestDigest(apiURL, repo, tag, username, password string) (string, error) {
147		rawURL := fmt.Sprintf("%s/v2/%s/manifests/%s", strings.TrimSuffix(apiURL, "/"), repo, url.PathEscape(tag))
148		resp, _, err := registryDo(http.MethodHead, rawURL, manifestAccept, username, password, "")
149		if err != nil {
150			return "", err
151		}
152		_ = resp.Body.Close()
153		if resp.StatusCode != http.StatusOK {
154			return "", fmt.Errorf("registry returned %d for %s:%s", resp.StatusCode, repo, tag)
155		}
156		digest := resp.Header.Get("Docker-Content-Digest")
157		if digest == "" {
158			return "", fmt.Errorf("registry gave no digest for %s:%s", repo, tag)
159		}
160		return digest, nil
161	}
162	
163	// RegistryAPIBase is the v2 API root of a registry named in an image reference:
164	// Docker Hub has its own host, a local registry is reached over plain HTTP, and
165	// everything else over HTTPS. An empty registry is Docker Hub.
166	func RegistryAPIBase(registry string) string {
167		switch {
168		case registry == "":
169			return "https://registry-1.docker.io"
170		case strings.HasPrefix(registry, "localhost") || strings.HasPrefix(registry, "127.0.0.1"):
171			return "http://" + registry
172		}
173		return "https://" + registry
174	}
175	
176	// resolveNext is the URL a Link header's rel="next" points to, resolved against
177	// the page it came with — registries send it as a path — or "" when there is
178	// none. A next link that leads back to the page just read ends the walk rather
179	// than looping on it.
180	func resolveNext(current, link string) string {
181		for _, part := range strings.Split(link, ",") {
182			target, rel, ok := strings.Cut(strings.TrimSpace(part), ";")
183			if !ok || !strings.Contains(rel, `rel="next"`) {
184				continue
185			}
186			target = strings.Trim(strings.TrimSpace(target), "<>")
187			base, err := url.Parse(current)
188			if err != nil {
189				return ""
190			}
191			ref, err := url.Parse(target)
192			if err != nil {
193				return ""
194			}
195			if next := base.ResolveReference(ref).String(); next != current {
196				return next
197			}
198		}
199		return ""
200	}
201	
202	// exchangeBearerToken fetches a bearer token from the registry's token endpoint.
203	func exchangeBearerToken(challenge, username, password string) (string, error) {
204		params := parseBearerChallenge(challenge)
205		realm, ok := params["realm"]
206		if !ok {
207			return "", fmt.Errorf("bearer challenge missing realm")
208		}
209		u, err := url.Parse(realm)
210		if err != nil {
211			return "", fmt.Errorf("parse realm %q: %w", realm, err)
212		}
213		q := u.Query()
214		if s, ok := params["service"]; ok {
215			q.Set("service", s)
216		}
217		if s, ok := params["scope"]; ok {
218			q.Set("scope", s)
219		}
220		u.RawQuery = q.Encode()
221	
222		req, err := http.NewRequest("GET", u.String(), nil)
223		if err != nil {
224			return "", fmt.Errorf("build token request: %w", err)
225		}
226		if username != "" && password != "" {
227			req.SetBasicAuth(username, password)
228		}
229		resp, err := registryHTTPClient.Do(req)
230		if err != nil {
231			return "", fmt.Errorf("fetch token: %w", err)
232		}
233		defer func() { _ = resp.Body.Close() }()
234		if resp.StatusCode != http.StatusOK {
235			return "", fmt.Errorf("token endpoint returned %d", resp.StatusCode)
236		}
237		body, err := io.ReadAll(resp.Body)
238		if err != nil {
239			return "", fmt.Errorf("read token response: %w", err)
240		}
241		var result struct {
242			Token       string `json:"token"`
243			AccessToken string `json:"access_token"`
244		}
245		if err := json.Unmarshal(body, &result); err != nil {
246			return "", fmt.Errorf("decode token response: %w", err)
247		}
248		if result.Token != "" {
249			return result.Token, nil
250		}
251		if result.AccessToken != "" {
252			return result.AccessToken, nil
253		}
254		return "", fmt.Errorf("token response contained no token field")
255	}
256	
257	// parseBearerChallenge parses the value portion of a Www-Authenticate: Bearer header.
258	// Example: `realm="https://auth.docker.io/token",service="registry.docker.io"`
259	func parseBearerChallenge(s string) map[string]string {
260		params := make(map[string]string)
261		for _, part := range strings.Split(s, ",") {
262			part = strings.TrimSpace(part)
263			idx := strings.IndexByte(part, '=')
264			if idx < 0 {
265				continue
266			}
267			key := strings.TrimSpace(part[:idx])
268			val := strings.Trim(strings.TrimSpace(part[idx+1:]), `"`)
269			params[key] = val
270		}
271		return params
272	}
