	m.cursorStack = append(m.cursorStack, m.table.Cursor())
	// Push current group onto navigation stack
	m.navigationStack = append(m.navigationStack, m.currentGroupNode)
	m.currentGroupNode = node
	m.activeTabIndex = m.tabCount() - 1

	// A level the index knows goes on screen at once, and is read again from
	// the forge behind it; one it does not know waits for the forge, as every
	// level used to.
	if node.Children == nil {
		if children, known := m.indexedLevel(node); known {
			m.showIndexedLevel(node, children)
		} else {
			node.Loading = true
			node.Blocking = true
			m.loading = true
			m.updateTableRows()
			return m, tea.Batch(m.spinner.Tick, m.loadChildren(node))
		}
	}
	m.updateTableRows()
	m.table.GotoTop()
	if !node.Fresh {
		return m, m.refreshLevel(node)
	}
	return m, nil
}

// handleDrillUp handles backspace key - navigate back to parent
