// matchesQuery tests the query against each searchable column and then against
// the row as a whole.
//
// The row-level pass is what keeps a query spanning two fields — "tcp 22" over a
// ports list — working: netdiag matched against a joined haystack while the
// other four filter loops matched per field, and per field alone would have
// quietly dropped those matches on migration. Matching both ways is a superset
// of either, so no view loses anything and they all gain the same thing.
func (m *Model[T]) matchesQuery(item T, query string) bool {
	var joined strings.Builder
	for _, c := range m.cfg.Columns {
		if c.Search == nil {
			continue
		}
		value := c.Search(item)
		if strings.Contains(strings.ToLower(value), query) {
			return true
		}
		if joined.Len() > 0 {
			joined.WriteByte(' ')
		}
		joined.WriteString(value)
	}
	return strings.Contains(strings.ToLower(joined.String()), query)
}

// sorted orders the visible slice. SliceStable, because sort.Slice is not and
// two rows equal on the sort column would otherwise swap between rebuilds.
func (m *Model[T]) sorted(items []T) []T {
	if m.sortColumn < 0 {
		return items
	}
	less := m.cfg.Columns[m.sortColumn].Less // never nil — see New
	desc := m.sortDesc
	sort.SliceStable(items, func(i, j int) bool {
		if desc {
			return less(items[j], items[i])
		}
		return less(items[i], items[j])
	})
	return items
}

// Span is one coloured run of a multi-run cell (Column.Spans): Width cells of
// the cell's already-fitted text, painted with Style. Style must not carry
// Width, Padding or Margin: they would change the cell's width (as for Cut).
type Span struct {
	Width int
	Style lipgloss.Style
}

// IndicatorColumn builds the activity column (Rule 125 shape: untitled, fixed,
// IconColumnWidth). It is the only way a view builds one. Only the first column
// carrying an Indicator is honoured (Model.indicatorAt); later ones are ignored.
func IndicatorColumn[T any](state func(T) indicator.State,
	rest func(T) string, restStyle func(T) lipgloss.Style) Column[T] {
	c := Column[T]{
		Sizing: SizingFixed, MinWidth: IconColumnWidth,
		Indicator: state,
		Cell: func(item T) string {
			if rest == nil {
				return ""
			}
			return rest(item)
		},
	}
	if restStyle != nil {
		c.Style = restStyle
	}
	return c
}

// SetBlinkPhase sets the phase read at render. Read at render; nothing is rebuilt.
func (m *Model[T]) SetBlinkPhase(on bool) { m.blinkOn = on }

// BlinkPhase reports the current blink phase.
func (m *Model[T]) BlinkPhase() bool { return m.blinkOn }

// Path is what ties a file to its surface, and it is there so the
// declaration is checkable: without it, "these letters are local to this
// view" is verified by merging every list, and `l` declared for netdiag
// would excuse `l` in the registries. Matching is done on the longest
// prefix, so netdiag/ports can narrow down netdiag.
type Surface struct {
	Name string
	Path string
	Keys []string
}

// localToggles inventories the lowercase letters used as display or filter
// toggles. They change nothing, so their meaning is local and the same
// letter can serve twice without contradiction — `l` is the protocol in
// netdiag and the LOW severity in security.
//
// A file that matches no surface is entitled to no lowercase letter at
// all: that is the default, and it is what makes the list worth keeping
// up to date.
var localToggles = []Surface{
	{"containers", "ui/containers/", []string{"r", "p", "s", "t", "z"}},
	{"viewer", "ui/viewer/", []string{"f", "c", "w", "v", "t", "n", "g", "s"}},
	{"netdiag/ports", "ui/netdiag/ports_model.go", []string{"t", "u", "l", "e", "n", "z"}},
	{"netdiag/checks", "ui/netdiag/", []string{"p"}},
	{"oci/browser", "ui/oci_resources/browser_", []string{"r"}},
	{"security/findings", "ui/security/", []string{"c", "h", "m", "l"}},
	// g opens the fuzzy-find prompt across the whole workspaces tree. Same
	// justification as the viewer's g: the jump takes an argument (the typed
	// query), which is not a role home/end/G could ever cover.
	{"workspaces", "ui/workspaces/", []string{"g"}},
	// The same prompt over the forge index: every namespace and repository
	// the session can see, at any depth.
	{"forge/explorer", "ui/forge/explorer/", []string{"g"}},
}

